"""navera_lite/ros/convert.py — from NAVERA Lite's Python objects to standard ROS 2 messages and back:
Estimate ↔ sensor_msgs/NavSatFix, the judge's decision → diagnostic_msgs/DiagnosticStatus. Part of NAVERA
Lite, the course's teaching stack (mission 09). Written for the course; it is not NAVERA code.

On the wire (lesson 12 §1):
  NavSatFix.header.stamp      = the instant the position was MEASURED (Estimate.stamp_s)
  NavSatFix.header.frame_id   = the source ("gps", "day", "night", "celestial")
  NavSatFix.status.status     = -1 (STATUS_NO_FIX) when the source has no position (valid=False), else 0
  position_covariance(_type)  = Estimate.cov / cov_type, copied as floats
A fix topic carries measurements only: an old position is never published again as if it were new.

The judge's status is a DiagnosticStatus: level OK = FIX, WARN = DEGRADED, ERROR = NO_FIX, STALE = STARTING;
name "navera_lite/arbiter"; message = the reason in words; values = KeyValue strings, keys in STATUS_KEYS
plus one "src.<source>" per source. NAVERA uses its own typed messages (lessons describe them in words);
NAVERA Lite uses only standard messages, so it needs no build, and pays with string values: the key list is
a written contract.
"""
import math

from builtin_interfaces.msg import Time
from diagnostic_msgs.msg import DiagnosticStatus, KeyValue
from sensor_msgs.msg import NavSatFix, NavSatStatus

from navera_lite.estimate import Estimate

STATUS_NAME = "navera_lite/arbiter"
STATUS_KEYS = ("state", "source", "sigma_m", "age_s", "use_eligible", "imu")   # then src.gps, src.day, …
LEVELS = {"FIX": DiagnosticStatus.OK, "DEGRADED": DiagnosticStatus.WARN, "NO_FIX": DiagnosticStatus.ERROR,
          "STARTING": DiagnosticStatus.STALE}


# from mission 09 — finished: read it, use it, do not change it
def stamp_to_s(stamp):
    """A builtin_interfaces/Time (header.stamp) in seconds, a float.

    Example: stamp_to_s(Time(sec=100, nanosec=250_000_000)) → 100.25
    """
    return stamp.sec + stamp.nanosec * 1e-9


# from mission 09 — finished: read it, use it, do not change it
def s_to_stamp(t_s):
    """Seconds (a float ≥ 0) → a builtin_interfaces/Time.

    Example: s_to_stamp(100.25) → Time(sec=100, nanosec=250000000)
    """
    sec = math.floor(t_s)
    nanosec = int(round((t_s - sec) * 1e9))
    if nanosec >= 1_000_000_000:
        sec, nanosec = sec + 1, nanosec - 1_000_000_000
    return Time(sec=int(sec), nanosec=nanosec)


# from mission 09 — finished: read it, use it, do not change it
def to_navsatfix(est):
    """An Estimate as a sensor_msgs/NavSatFix (the mapping in this file's header).

    Example: to_navsatfix(Estimate("day", 35.83, 10.64, 100.5)).header.frame_id → "day"
    """
    msg = NavSatFix()
    msg.header.stamp = s_to_stamp(est.stamp_s)
    msg.header.frame_id = est.source
    msg.status.status = NavSatStatus.STATUS_FIX if est.valid else NavSatStatus.STATUS_NO_FIX
    msg.status.service = NavSatStatus.SERVICE_GPS if est.source == "gps" else 0
    msg.latitude = float(est.lat)
    msg.longitude = float(est.lon)
    msg.altitude = float(est.alt_m)
    msg.position_covariance = [float(v) for v in est.cov]
    msg.position_covariance_type = int(est.cov_type)
    return msg


# from mission 09 — finished: read it, use it, do not change it
def from_navsatfix(msg, source=None, now_s=None):
    """A sensor_msgs/NavSatFix as an Estimate. source: the name to use (default: header.frame_id — a fix
    topic of NAVERA Lite always fills it); now_s: when it was received (stored in t_recv_s).

    Example: from_navsatfix(to_navsatfix(Estimate("gps", 35.83, 10.64, 7.0)), now_s=7.2).t_recv_s → 7.2
    """
    valid = msg.status.status >= NavSatStatus.STATUS_FIX
    return Estimate(source=source or msg.header.frame_id, lat=msg.latitude, lon=msg.longitude,
                    stamp_s=stamp_to_s(msg.header.stamp), cov=tuple(float(v) for v in msg.position_covariance),
                    cov_type=int(msg.position_covariance_type), alt_m=msg.altitude, valid=valid,
                    reason="" if valid else "the source says: no fix", t_recv_s=now_s)


# from mission 09 — finished: read it, use it, do not change it
def make_status(state, reason, values):
    """The judge's decision as a diagnostic_msgs/DiagnosticStatus.

    state: "FIX", "DEGRADED", "NO_FIX" or "STARTING"; reason: one sentence; values: a dict str → anything
    (each value is written with str(); the "state" key is added).
    Example: make_status("FIX", "gps: σ 3.0 m", {"source": "gps"}).level → DiagnosticStatus.OK (b'\\x00')
    """
    msg = DiagnosticStatus()
    msg.level = LEVELS[state]
    msg.name = STATUS_NAME
    msg.message = reason
    msg.hardware_id = "navera_lite"
    items = {"state": state}
    items.update(values)
    msg.values = [KeyValue(key=str(k), value=str(v)) for k, v in items.items()]
    return msg


# from mission 09 — finished: read it, use it, do not change it
def status_values(msg):
    """The values of a DiagnosticStatus as a dict str → str.

    Example: status_values(make_status("NO_FIX", "no source", {"source": ""}))["state"] → "NO_FIX"
    """
    return {kv.key: kv.value for kv in msg.values}


# from mission 09 — finished: read it, use it, do not change it
def level_of(msg):
    """The level of a DiagnosticStatus as an int (the field is one byte: b'\\x01' → 1).

    Example: level_of(make_status("DEGRADED", "day: σ unknown", {})) → 1
    """
    lv = msg.level
    return lv[0] if isinstance(lv, (bytes, bytearray)) else int(lv)
